import json

for path, gal in [
    ("/app/frontend/src/i18n/en.json", {
        "kicker": "STORYBOARD GALLERY",
        "title": "Cinematic frames, generated by AI",
        "subtitle": "Real storyboard frames FrameFlow can generate for your production — from a single brief.",
        "captions": [
            "Coastal drive · Golden hour",
            "Interior · Ambient glow",
            "City night · Neon",
            "Detail · Studio light",
            "Lifestyle · Sunset",
            "Aerial · Desert highway",
        ],
    }),
    ("/app/frontend/src/i18n/it.json", {
        "kicker": "GALLERIA STORYBOARD",
        "title": "Fotogrammi cinematografici, generati dall'AI",
        "subtitle": "Fotogrammi storyboard reali che FrameFlow può generare per la tua produzione — da un solo brief.",
        "captions": [
            "Guida costiera · Ora d'oro",
            "Interni · Luce ambientale",
            "Notte in città · Neon",
            "Dettaglio · Luce da studio",
            "Lifestyle · Tramonto",
            "Aerea · Autostrada nel deserto",
        ],
    }),
]:
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)
    data["landing"]["gallery"] = gal
    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    print("updated", path)
